const codigo = String($('Validar solicitud del chat').first().json.codigo_estudiante || '');
const ETIQUETA_MCP = 'Base de datos académica iBanú (MCP)';
const agente = $('Orientador iBanú').first().json || {};
let texto = String($input.first().json.guardrailsInput || agente.output || '').trim();
const titulos = [];
let usoMcp = false;
let otroCodigo = false;
const pasos = Array.isArray(agente.intermediateSteps) ? agente.intermediateSteps : [];
for (const paso of pasos) {
  const herramienta = String((paso.action && paso.action.tool) || '');
  const obs = typeof paso.observation === 'string' ? paso.observation : JSON.stringify(paso.observation || '');
  const fallo = /^\s*"?(error|\[error)/i.test(obs) || /"isError"\s*:\s*true/.test(obs);
  if (/documental|conocimiento/i.test(herramienta)) {
    if (fallo) continue;
    const re = /\\*"titulo\\*"\s*:\s*\\*"([^"\\]+)/g;
    let m;
    while ((m = re.exec(obs)) !== null) {
      const t = m[1].trim();
      if (t && !titulos.includes(t)) titulos.push(t);
    }
    continue;
  }
  const entrada = paso.action && paso.action.toolInput;
  const cod = entrada && typeof entrada === 'object' ? String(entrada.codigo_estudiante || '').trim() : '';
  if (cod && cod.toUpperCase() !== codigo.toUpperCase()) otroCodigo = true;
  if (obs && !fallo) usoMcp = true;
}
if (otroCodigo) {
  return [{ json: { respuesta: 'Solo puedo mostrarte tu propia información académica. Si necesitas datos de otra persona, esa persona debe consultarlos directamente por los canales institucionales. Con gusto te ayudo con tu matrícula, tu avance o tus estrategias de estudio.', fuentes: [], bloqueado: true, motivo: 'datos_de_terceros' } }];
}
const lineaFuentes = /(?:^|\n)[ \t]*\**Fuentes[^:\n]*:\**[ \t]*(.+)$/im;
if (!titulos.length) {
  const linea = texto.match(lineaFuentes);
  if (linea && !usoMcp) {
    for (const t of linea[1].split(/;|\|/)) {
      const limpio = t.replace(/[*_]/g, '').trim();
      if (limpio && limpio !== ETIQUETA_MCP && !titulos.includes(limpio)) titulos.push(limpio);
    }
  }
}
const fuentes = (usoMcp ? [ETIQUETA_MCP] : []).concat(titulos);
texto = texto.replace(lineaFuentes, '').trimEnd();
if (fuentes.length) texto += '\n\nFuentes: ' + fuentes.join('; ');
texto = texto.replace(/\bU\d{8}\b/g, (c) => (c.toUpperCase() === codigo.toUpperCase() ? c : '[código oculto]'));
if (texto.length > 6000) texto = texto.slice(0, 6000) + '...';
if (!texto) texto = 'No logré generar una respuesta. Intenta reformular tu pregunta.';
return [{ json: { respuesta: texto, fuentes, bloqueado: false, motivo: null } }];

