const docs = $('Leer documentos académicos').all().map((i) => i.json);
const fragmentos = $input.all().map((i) => i.json);
const porDocumento = {};
for (const f of fragmentos) {
  if (!f || !f.documento_id) continue;
  (porDocumento[f.documento_id] = porDocumento[f.documento_id] || []).push(f);
}

function limpiar(t) {
  return String(t || '')
    .split('\n')
    .filter((l) => !/^\s*(DOC\d+-FO-\d+|Hoja\s+\d+\s+de\s+\d+)\s*$/i.test(l))
    .join('\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function unirSinSolape(lista) {
  let texto = '';
  for (const f of lista) {
    const c = String(f.contenido || '');
    if (!texto) { texto = c; continue; }
    const max = Math.min(450, texto.length, c.length);
    let solape = 0;
    for (let n = max; n >= 20; n--) {
      if (texto.endsWith(c.slice(0, n))) { solape = n; break; }
    }
    texto += solape ? c.slice(solape) : '\n\n' + c;
  }
  return texto;
}

const salida = [];
for (const d of docs) {
  if (d.activo === false) continue;
  const lista = (porDocumento[d.id] || []).slice().sort((a, b) => a.numero_fragmento - b.numero_fragmento);
  if (!lista.length) continue;
  const titulo = String(d.nombre_original || d.nombre_archivo || '').replace(/\.[A-Za-z0-9]{2,4}$/, '').replace(/_+/g, ' ').trim();
  const categoria = String(d.categoria || '').toLowerCase();
  let tipo = 'programa';
  if (categoria === 'reglamento') tipo = 'reglamento';
  else if (categoria === 'materias') tipo = 'guia_catedra';
  else if (/competencias/i.test(titulo + ' ' + (d.descripcion || ''))) tipo = 'competencias';
  const meta0 = (lista[0] && lista[0].metadata) || {};
  const sintetico = lista.some((f) => JSON.stringify(f.metadata || {}).toUpperCase().includes('SINTETICO'));
  let codigoAsignatura = meta0.codigo_guia || '';
  if (!codigoAsignatura) {
    const m = (String(d.nombre_archivo || '') + ' ' + String(d.observaciones || '')).match(/[A-Z]{4}\d{5}/);
    if (m) codigoAsignatura = m[0];
  }
  const doc = {
    documento_id: String(d.id),
    titulo: titulo || String(d.nombre_archivo || 'Documento'),
    tipo,
    fuente: String(d.nombre_archivo || ''),
    version: String(d.version_documento || ''),
    sintetico,
    codigo_asignatura: String(codigoAsignatura || ''),
  };
  if (tipo === 'reglamento') {
    doc.piezas = lista.map((f) => ({
      texto: limpiar(f.contenido),
      articulo: String((f.metadata && f.metadata.numero_articulo) || ''),
      capitulo: String((f.metadata && f.metadata.capitulo) || ''),
      seccion: String(f.seccion || ''),
      pagina: String(f.numero_pagina || ''),
    })).filter((p) => p.texto);
    doc.texto = doc.piezas.map((p) => p.texto).join('\n\n');
  } else {
    doc.texto = limpiar(unirSinSolape(lista));
  }
  salida.push({ json: doc });
}
return salida;

let docs = [];
