  const d = item.json;
  const base = {
    documento_id: d.documento_id,
    titulo: d.titulo,
    tipo: d.tipo,
    fuente: d.fuente,
    version: d.version || '',
    sintetico: d.sintetico === true ? 'true' : 'false',
    codigo_asignatura: d.codigo_asignatura || '',
    articulo: '',
    capitulo: '',
    seccion: '',
    pagina: '',
  };
  if (Array.isArray(d.piezas) && d.piezas.length) {
    for (const p of d.piezas) {
      const prefijo = d.titulo + (p.capitulo ? ', ' + p.capitulo : '') + (p.articulo ? ', Artículo ' + p.articulo : '') + ': ';
      salida.push({ json: Object.assign({}, base, { articulo: p.articulo, capitulo: p.capitulo, seccion: p.seccion, pagina: p.pagina, texto: prefijo + p.texto }) });
    }
  } else {
    let prefijo = d.titulo + ': ';
    if (d.tipo === 'guia_catedra') prefijo = 'Guía de cátedra ' + d.titulo + (d.codigo_asignatura ? ' (' + d.codigo_asignatura + ')' : '') + ': ';
    salida.push({ json: Object.assign({}, base, { texto: prefijo + String(d.texto || '') }) });
  }
}
return salida.filter((u) => u.json.texto.length > 60);

